ImageCheck check_menu_image(const void* image) {
    auto result=check_executable_image(image,eu4_1375_profile());
    if(!result.compatible) return result;
    std::uintptr_t actual=0;
    std::memcpy(&actual,static_cast<const std::byte*>(image)+0x1d5a8e8,sizeof(actual));
    if(actual!=reinterpret_cast<std::uintptr_t>(image)+0x10d2e80) {
        result.compatible=false;
        result.error="Refused: frontend tick pointer mismatch at RVA 0x1d5a8e8.";
        return result;
    }
    ++result.checked_sites;
    return result;
}
